<!doctype html><html lang="fa" dir="rtl"><head><meta charset="utf-8"><style>body{font-family:DejaVu Sans,sans-serif;direction:rtl;color:#222;font-size:11px}.head{display:flex;justify-content:space-between;border-bottom:2px solid #222;padding-bottom:12px}.brand{font-size:24px;font-weight:bold}.meta{margin:16px 0;background:#f5f5f5;padding:10px}table{width:100%;border-collapse:collapse}th,td{border:1px solid #ddd;padding:8px;text-align:right}th{background:#f2f2f2}.totals{margin-top:15px;width:45%;margin-right:auto}.totals div{display:flex;justify-content:space-between;padding:5px}.total{font-size:14px;font-weight:bold;border-top:2px solid #222}</style></head><body><div class="head"><div class="brand">AUTO CAR</div><div>فاکتور فروش<br>{{ $invoice->number }}</div></div><div class="meta">شماره سفارش: {{ $order->number }} | تاریخ: {{ $order->created_at->format('Y/m/d H:i') }}</div><table><thead><tr><th>شرح</th><th>SKU</th><th>تعداد</th><th>قیمت واحد</th><th>جمع</th></tr></thead><tbody>@foreach($order->items as $item)<tr><td>{{ $item->name }}</td><td>{{ $item->sku }}</td><td>{{ $item->quantity }}</td><td>{{ number_format($item->unit_price) }}</td><td>{{ number_format($item->line_total) }}</td></tr>@endforeach</tbody></table><div class="totals"><div><span>جمع</span><b>{{ number_format($order->subtotal) }}</b></div><div><span>تخفیف</span><b>{{ number_format($order->discount_total) }}</b></div><div><span>ارسال</span><b>{{ number_format($order->shipping_total) }}</b></div><div class="total"><span>مبلغ نهایی</span><b>{{ number_format($order->grand_total) }} ریال</b></div></div></body></html>
